"use strict";(self.webpackChunksalat_e_mustaqeem_client=self.webpackChunksalat_e_mustaqeem_client||[]).push([[8312],{8312:e=>{e.exports=JSON.parse('{"eyebrow":"Nouveau dans Salat-e-Mustaqeem","lede":"R\xe9citez, et la page vous suit. Chaque mot s\u2019illumine d\u2019or \xe0 mesure que vous le prononcez, et ce que vous avez omis vous attend \xe0 la fin, marqu\xe9 avec douceur.","small":"Gratuit. Fonctionne hors ligne. Votre voix ne quitte jamais votre t\xe9l\xe9phone.","ctaAppStore":"T\xe9l\xe9charger sur l\u2019App Store","ctaPlay":"Disponible sur Google Play","mushafLabel":"D\xe9monstration : Al-F\u0101ti\u1e25ah s\u2019illumine mot apr\xe8s mot au fil de la r\xe9citation","status":{"listening":"\xc0 l\u2019\xe9coute\u2026","recited":"R\xe9cit\xe9e","review":"Verset {{n}} : <b>1 mot \xe0 revoir</b>","well":"Verset {{n}} \xb7 <b>bien r\xe9cit\xe9</b>"},"how":{"kicker":"Comment \xe7a marche","h2":"Trois moments, et rien entre vous et le Coran","sub":"Tasm\u012b\u02bf, c\u2019est le mot qu\u2019emploie le ma\xeetre de hifz pour dire \xab r\xe9cite-le-moi \xbb. Il \xe9coute comme un ma\xeetre patient : il suit, il remarque, et il attend.","recite":{"h3":"R\xe9citez","p":"Ouvrez n\u2019importe quel verset dans le lecteur, ou une le\xe7on de Hifz, et touchez la lampe. R\xe9citez \xe0 votre rythme, comme devant votre ma\xeetre."},"follows":{"h3":"La page vous suit","p":"Le mot que vous prononcez s\u2019illumine. La page tourne d\u2019elle-m\xeame. \xc0 la fin du verset, vous voyez ce qu\u2019il faut revoir : une vague l\xe9g\xe8re sous un mot omis, un trait ambr\xe9 sous un mot prononc\xe9 autrement."},"hear":{"h3":"\xc9coutez le mot","p":"Touchez un mot marqu\xe9 pour entendre ce seul mot, tir\xe9 de la r\xe9citation m\xeame du qari. Puis r\xe9citez de nouveau le verset. Jamais de note : seulement \xab 2 mots \xe0 revoir \xbb.","youSaid":"Vous avez dit","ayahSays":"Le verset dit"}},"hifz":{"kicker":"Pour le hifz","h2":"Teste-moi : la page reste voil\xe9e jusqu\u2019\xe0 ce que vous la r\xe9citiez","sub":"Depuis n\u2019importe quelle le\xe7on de Hifz, activez \xab Teste-moi \xbb. Le verset est masqu\xe9, et chaque mot ne se d\xe9voile que lorsque vous le r\xe9citez correctement. C\u2019est ce qui se rapproche le plus d\u2019une s\xe9ance devant votre ma\xeetre, \xe0 toute heure de la nuit.","veilLabel":"Teste-moi : les mots se d\xe9voilent \xe0 mesure qu\u2019ils sont r\xe9cit\xe9s"},"muallim":{"kicker":"Bient\xf4t","chip":"Exp\xe9rimental","h2":"Le Mu\u02bfallim : le tajwid, \xe0 la mesure de votre propre rythme","sub1":"Un petit mod\xe8le d\u2019\xe9coute que nous construisons nous-m\xeames, sur le t\xe9l\xe9phone comme le reste de Tasm\u012b\u02bf. Il mesure chaque madd et chaque ghunnah en \u1e25arak\u0101t calcul\xe9es \xe0 partir de votre propre r\xe9citation : un murattal lent et un \u1e25adr rapide sont ainsi jug\xe9s de la m\xeame fa\xe7on, et il marque les endroits qu\u2019un ma\xeetre annoterait au crayon.","sub2":"Il commence par le madd et la ghunnah, puis la qalqalah. Lorsqu\u2019il a un doute, il se tait : une r\xe9citation correcte ne doit jamais \xeatre marqu\xe9e comme fautive. Il ne remplacera pas votre ma\xeetre ; il vous aide \xe0 arriver pr\xe9par\xe9.","label":"Le Mu\u02bfallim marque un madd tenu deux temps l\xe0 o\xf9 quatre \xe0 cinq sont demand\xe9s","cap":"Madd munfa\u1e63il : tenu <b>2</b>, demand\xe9 <b>4\u20135</b>"},"promise":{"kicker":"Notre promesse","h2":"Votre r\xe9citation reste entre vous et Allah","items":[{"b":"Sur votre t\xe9l\xe9phone","span":"Tasm\u012b\u02bf \xe9coute sur l\u2019appareil lui-m\xeame. Votre voix n\u2019est jamais envoy\xe9e nulle part, pas m\xeame \xe0 nous."},{"b":"Jamais enregistr\xe9e","span":"Le son ne vit qu\u2019un instant en m\xe9moire, puis dispara\xeet. Rien n\u2019est conserv\xe9."},{"b":"Hors ligne","span":"Apr\xe8s un unique t\xe9l\xe9chargement de 88 Mo, il fonctionne en mode avion, \xe0 la mosqu\xe9e, partout."},{"b":"Gratuit","span":"Sans abonnement, sans publicit\xe9. Une sadaqa jariya, in sh\u0101\u02be All\u0101h."}]},"who":{"kicker":"Pens\xe9 pour","h2":"Chaque r\xe9citant, \xe0 chaque \xe9tape","cards":[{"h3":"\xc9l\xe8ves de hifz","p":"R\xe9visez une le\xe7on seul, rattrapez le mot qui \xe9chappe, et arrivez en classe pr\xeat."},{"h3":"Enfants","p":"De grands mots dor\xe9s, des marques douces, aucune note. Bient\xf4t : la Qaida, lettre par lettre, d\u2019Alif \xe0 Y\u0101."},{"h3":"D\xe9butants","p":"R\xe9citer seul intimide. Tasm\u012b\u02bf marche \xe0 vos c\xf4t\xe9s, verset apr\xe8s verset, \xe0 votre rythme."}],"tag":"Qaida bient\xf4t"},"honest":{"h3":"Il v\xe9rifie les mots, pas le tajwid","p":"Tasm\u012b\u02bf vous indique si vous avez dit les bons mots dans le bon ordre. Il ne juge ni les makharij, ni le madd, ni les autres r\xe8gles du tajwid, et ce n\u2019est pas un ma\xeetre. R\xe9citez aussi devant un ma\xeetre. Tasm\u012b\u02bf est marqu\xe9 Exp\xe9rimental tant que nous continuons \xe0 l\u2019am\xe9liorer."},"faq":{"kicker":"Questions","h2":"Avant de commencer","items":[{"q":"Ma r\xe9citation est-elle enregistr\xe9e ou envoy\xe9e ?","a":"Non. L\u2019\xe9coute se fait enti\xe8rement sur votre t\xe9l\xe9phone. Le son n\u2019est jamais stock\xe9 ni envoy\xe9, ni \xe0 nous ni \xe0 personne."},{"q":"Fonctionne-t-il sans internet ?","a":"Oui, une fois le pack d\u2019\xe9coute de 88 Mo install\xe9 sur votre t\xe9l\xe9phone. Il se t\xe9l\xe9charge en Wi\u2011Fi par d\xe9faut ; vous pouvez choisir les donn\xe9es mobiles."},{"q":"Sur quels t\xe9l\xe9phones fonctionne-t-il ?","a":"Sur les iPhone et t\xe9l\xe9phones Android qui font tourner Salat-e-Mustaqeem. Sur les t\xe9l\xe9phones plus anciens, il s\u2019ajuste pour que la lumi\xe8re dor\xe9e suive le rythme."},{"q":"Peut-il v\xe9rifier mon tajwid ?","a":"Pas encore, mais le Mu\u02bfallim arrive. Il commencera par la dur\xe9e du madd et de la ghunnah, mesur\xe9e selon votre propre rythme, et se taira chaque fois qu\u2019il a un doute. D\u2019ici l\xe0, r\xe9citez devant un ma\xeetre pour le tajwid."},{"q":"Convient-il aux enfants ?","a":"Oui. Aucune note, seulement des marques douces. Un mode Qaida pour apprendre les lettres arrive bient\xf4t."}]},"final":{"cite":"\xab Et r\xe9cite le Coran lentement et clairement. \xbb Al-Muzzammil 73:4","h2":"Commencez par un verset ce soir"},"credit":"Le mod\xe8le vocal de Tasm\u012b\u02bf est \xab tilawi-fastconformer-quran \xbb de muhdur, sous licence CC BY 4.0, affin\xe9 \xe0 partir du FastConformer arabe de NVIDIA (CC BY 4.0). Texte du Coran : Tanzil."}')}}]);